WITH joined AS (SELECT src.id, src.order_id, src.carrier, src.cost, src.status, o.shipping_fee, o.order_date FROM shipments src INNER JOIN orders o ON src.order_id = o.id), metrics AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY status ORDER BY shipping_fee DESC, id) AS row_seq, FIRST_VALUE(cost, TRUE) OVER w_grp AS first_known_cost, NTILE(10) OVER (PARTITION BY carrier ORDER BY cost, id) AS cost_bucket FROM joined WINDOW w_grp AS (PARTITION BY status ORDER BY shipping_fee, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), deduped AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY carrier ORDER BY order_date DESC, id) AS dedup_rank FROM metrics QUALIFY dedup_rank = 1), enriched AS (SELECT id, carrier, status, order_date, row_seq, first_known_cost, cost_bucket, LEAD(shipping_fee, 1) OVER (PARTITION BY order_id ORDER BY shipping_fee, id) AS next_shipping_fee, SUM(cost) OVER (ORDER BY first_known_cost, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_cost FROM deduped) SELECT status, SUM(CASE WHEN carrier = 'DHL' THEN cumulative_cost ELSE 0 END) AS dhl_cumulative_cost, ROUND(AVG(cumulative_cost), 2) AS avg_cumulative_cost, SUM(CASE WHEN status = 'RETURNED' THEN row_seq ELSE 0 END) AS returned_row_seq, APPROX_PERCENTILE(cost_bucket, ARRAY(0.25, 0.5, 0.75)) AS cost_bucket_quartiles, SUM(CASE WHEN carrier = 'UPS' THEN row_seq ELSE 0 END) AS ups_row_seq FROM enriched GROUP BY status HAVING SUM(CASE WHEN carrier = 'DHL' THEN cumulative_cost ELSE 0 END) > 0 ORDER BY avg_cumulative_cost DESC;
